#requires -version 5.1
# White's Game Lab V2 — Self-contained GitHub Profile publisher
# Use: powershell -ExecutionPolicy Bypass -File "$HOME\Downloads\White_Game_Lab_V2_Publish.ps1"
$ErrorActionPreference = 'Stop'
$gitExe = Get-Command git -ErrorAction SilentlyContinue
if (-not $gitExe) { throw 'Git 未安装。请安装 Git for Windows 并登录 GitHub，然后重新运行。' }
$repo = 'https://github.com/shaobaichen/shaobaichen.git'
$now = Get-Date -Format 'yyyyMMdd-HHmmss'
$target = Join-Path $env:TEMP ("WhiteGameLabV2-" + $now + "-" + $PID)
Write-Host '正在读取 GitHub 个人主页仓库...' -ForegroundColor Cyan
& git clone --depth 1 --branch main $repo $target
if ($LASTEXITCODE -ne 0) { throw '无法克隆仓库，请先检查网络、GitHub 登录权限及 Git 配置。' }
$origin = (& git -C $target remote get-url origin).Trim()
if ($LASTEXITCODE -ne 0 -or $origin -notmatch 'shaobaichen/shaobaichen(\.git)?$') { throw "仓库远端校验失败：$origin" }
$backup = Join-Path $target 'backup'
New-Item -ItemType Directory -Path $backup -Force | Out-Null
$oldReadme = Join-Path $target 'README.md'
if (Test-Path $oldReadme) {
  Copy-Item $oldReadme (Join-Path $backup "README-before-v2-$now.md") -Force
}
function Write-VerifiedAsset([string]$relativePath, [string]$encoded, [string]$expectedSha256) {
  $dest = Join-Path $target ($relativePath.Replace('/', [IO.Path]::DirectorySeparatorChar))
  $folder = Split-Path -Parent $dest
  if (-not (Test-Path $folder)) { New-Item -ItemType Directory -Path $folder -Force | Out-Null }
  [IO.File]::WriteAllBytes($dest, [Convert]::FromBase64String($encoded))
  $digest = (Get-FileHash $dest -Algorithm SHA256).Hash.ToLowerInvariant()
  if ($digest -ne $expectedSha256) { throw "文件校验失败：$relativePath" }
  Write-Host "已准备：$relativePath"
}
