Write-Host '正在核对并提交修改...' -ForegroundColor Cyan
& git -C $target add README.md assets backup
if ($LASTEXITCODE -ne 0) { throw 'git add 失败。' }
& git -C $target diff --cached --check
if ($LASTEXITCODE -ne 0) { throw '检查发现空白字符或文件问题，已停止。' }
& git -C $target commit -m 'docs(profile): V2 independent game showcase cabinets'
if ($LASTEXITCODE -ne 0) { throw 'git commit 失败。可能缺少 Git 用户名或邮箱配置。' }
Write-Host '正在推送 GitHub main 分支...' -ForegroundColor Cyan
& git -C $target push origin main
if ($LASTEXITCODE -ne 0) { throw "Push 失败，提交与备份仍保留在：$target" }
